def transform(grid):
    a=[row[:] for row in grid]; n=len(a); m=len(a[0])
    ones=sorted((r,c) for r in range(n) for c in range(m) if a[r][c]==1)
    r,c=ones[-1]; trigger=None; adjacent=False
    if c+1<m and grid[r][c+1]==2:
        trigger=(r,c+1); adjacent=True
    else:
        rr,cc=r+1,c+1
        while rr<n and cc<m:
            if grid[rr][cc]==2: trigger=(rr,cc); break
            rr+=1;cc+=1
    branch=False
    if trigger:
        tr,tc=trigger; row=grid[tr]; left=tc; right=tc
        while left and row[left-1]==2:left-=1
        while right+1<m and row[right+1]==2:right+=1
        branch=(right-left+1<=5 or right-left+1>=12)
    nextred=n
    if branch:
        for rr in range(tr+1,n):
            if 2 in grid[rr]:nextred=rr;break
    rr,cc=r+1,c+1
    while rr<nextred and cc<m:
        a[rr][cc]=1;rr+=1;cc+=1
    if branch:
        mc=tc if adjacent else tc+1
        for sc,dc in [(mc,1),(mc+6,1),(mc+6,-1),(mc+12,-1)]:
            rr,cc=tr+1,sc
            while rr<nextred and 0<=cc<m:
                a[rr][cc]=1;rr+=1;cc+=dc
    return a
